'use strict';
const fs=require('fs'),os=require('os'),path=require('path');
const {spawnSync}=require('child_process');
const repo=path.resolve(__dirname,'..','..');
const registry=require(path.join(repo,'shared','code-capability-fabric','language-organs','registry.js'));
const organ=registry.getByLanguageId('opencl');
if(!organ)throw Error('REQUIRED_NATIVE_ORGAN_MISSING:opencl');
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'axm-required-native-'));
const file=path.join(dir,'probe.cl');
fs.writeFileSync(file,'__kernel void add(__global int*x){size_t i=get_global_id(0);x[i]+=1;}\n','utf8');
const started=Date.now();
const r=spawnSync('clang',['-x','cl','-cl-std=CL1.2','-fsyntax-only',file],{cwd:repo,encoding:'utf8',timeout:15000,windowsHide:true});
const smoke={probeClass:'COMPILER_PARSE',command:'clang',args:['-x','cl','-cl-std=CL1.2','-fsyntax-only','<temp>/probe.cl'],status:r.status,signal:r.signal,error:r.error?String(r.error.message||r.error):null,durationMs:Date.now()-started,stdout:String(r.stdout||'').slice(0,1600),stderr:String(r.stderr||'').slice(0,1600)};
const pass=r.status===0&&!r.error;
const result={priority:organ.priority,organId:organ.organId,languageId:organ.languageId,displayName:organ.displayName,pathToolchainPresent:pass,availableToolchains:pass?['clang']:[],smokeDefined:true,smokePass:pass,smoke};
const summary={schema:'axm.code-language-toolchain-census/v2',status:'TEST',organCount:102,toolchainPresentCount:pass?1:0,smokeDefinedCount:1,smokePassCount:pass?1:0,smokeFailCount:pass?0:1,noSmokeDefinedCount:101,compilerOrAssemblerPassCount:pass?1:0,parserValidatorInterpreterPassCount:0,toolAvailabilityOnlyPassCount:0,compilerUniverseClaimed:false,runtimeCorrectnessClaimed:false,authority:'NONE',requiredCoverageSubset:true,passingOrgans:pass?['opencl']:[],failedSmokeOrgans:pass?[]:['opencl'],missingNativeProbe:[]};
const reportPath=process.env.AXM_TOOLCHAIN_REPORT||'required-native-gap-census.json';
fs.writeFileSync(reportPath,JSON.stringify({summary,results:[result]},null,2)+'\n','utf8');
console.log(JSON.stringify(summary,null,2));
console.log(`AXM_TOOLCHAIN_REPORT=${reportPath}`);
if(!pass)process.exitCode=1;
